def parse_count(value):
    """Parse a nonnegative decimal integer string.

    Surrounding whitespace is ignored. Blank or whitespace-only strings are
    treated as zero. Negative, fractional, and otherwise invalid values raise
    ``ValueError``.
    """
    text = value.strip()
    if not text:
        return 0
    if not text.isdecimal():
        raise ValueError("count must be a nonnegative decimal integer")
    return int(text)

import unittest
from counts import parse_count


class CountTests(unittest.TestCase):
    def test_positive(self):
        self.assertEqual(parse_count("12"), 12)

    def test_surrounding_whitespace(self):
        self.assertEqual(parse_count("  42\t\n"), 42)

    def test_blank_and_whitespace_only_return_zero(self):
        self.assertEqual(parse_count(""), 0)
        self.assertEqual(parse_count(" \t\n"), 0)

    def test_negative_raises_value_error(self):
        with self.assertRaises(ValueError):
            parse_count("-1")
        with self.assertRaises(ValueError):
            parse_count("  -12  ")

    def test_fractional_raises_value_error(self):
        with self.assertRaises(ValueError):
            parse_count("1.5")
        with self.assertRaises(ValueError):
            parse_count("  2.0  ")

    def test_noninteger_raises_value_error(self):
        for value in ("abc", "12x", "+12", "1e2"):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    parse_count(value)

